// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {W_WALLET, Log} from "../src/W_WALLET.sol";

uint256 constant VALUE_CAP = 1000000000000000000000000000000;

contract InvMutTest is Test {
    W_WALLET c;
    Log log_;

    function setUp() public { log_ = new Log(); c = new W_WALLET(address(log_)); }

    function testFuzz_property(address actor, uint256 amount, uint256 unlockTime) public {
        vm.assume(amount <= VALUE_CAP);
        vm.assume(actor != address(0));
        vm.assume(actor != address(c));
        amount = bound(amount, 1, 1000 ether);
        vm.deal(actor, amount);

        vm.prank(actor);
        c.Put{value: amount}(unlockTime);

        // After any Put, the Log history must contain at least one entry recording
        // that actor as sender with exactly that value.
        (address sender, , uint256 val, ) = log_.History(0);
        assertTrue(sender == actor && val == amount);
    }
}
